"""
End-to-End Pipeline & Integration Smoke Tests on Actual TMDB Artifacts.
"""

import os
import pytest
from src.recommender import ContentBasedRecommender


def test_production_artifacts_exist():
    """Verify production artifacts generated by train pipeline exist."""
    assert os.path.exists("models/movie_metadata.parquet")
    assert os.path.exists("models/feature_matrix.npz")
    assert os.path.exists("models/count_vectorizer.joblib")
    assert os.path.exists("models/training_metadata.json")


def test_production_recommender_inference():
    """Verify live inference against real TMDB dataset."""
    rec = ContentBasedRecommender.load_artifacts("models")
    assert len(rec.movies_df) == 4800

    # Query 'The Dark Knight'
    recs = rec.recommend("The Dark Knight", top_k=5)
    assert len(recs) == 5

    titles = [r["title"] for r in recs]
    # Check that Batman franchise titles appear in top recommendations
    assert any("Batman" in t or "Dark Knight" in t for t in titles)

    # Check structure of returned objects
    first_rec = recs[0]
    assert "movie_id" in first_rec
    assert "title" in first_rec
    assert "release_year" in first_rec
    assert "genres" in first_rec
    assert "similarity_percentage" in first_rec
    assert 0.0 <= first_rec["similarity_score"] <= 1.0


def test_production_recommender_query_avatar():
    """Verify recommendations for Avatar."""
    rec = ContentBasedRecommender.load_artifacts("models")
    recs = rec.recommend("Avatar", top_k=5)
    assert len(recs) == 5
    # Must not contain Avatar itself
    titles = [r["title"] for r in recs]
    assert "Avatar" not in titles
